from dataclasses import dataclass
from typing import Literal, NamedTuple

from beartype import beartype

ReadMode = Literal["sync", "unicast"]


@beartype
@dataclass(frozen=True, slots=True)
class BusConfig:
    device: str
    baudrate: int
    protocol: float
    expected_ids: tuple[int, ...]


@beartype
@dataclass(frozen=True, slots=True)
class JointRole:
    motor_id: int
    name: str


@beartype
@dataclass(frozen=True, slots=True)
class ArmConfig:
    bus: BusConfig
    roles: tuple[JointRole, ...] = ()
    physical_order_verified: bool = False

    def role(self, motor_id: int) -> str | None:
        return next((role.name for role in self.roles if role.motor_id == motor_id), None)


@beartype
@dataclass(frozen=True, slots=True)
class Fault:
    motor_id: int
    operation: str
    comm_result: int
    device_error: int
    message: str


@beartype
@dataclass(frozen=True, slots=True)
class Identity:
    motor_id: int
    model_number: int
    firmware_version: int | None
    observed_at: str
    device_error: int
    faults: tuple[Fault, ...] = ()


@beartype
@dataclass(frozen=True, slots=True)
class RegisterValue:
    name: str
    address: int
    size: int
    memory: str
    raw: int
    value: int
    device_alert: bool


class RegisterBatch(NamedTuple):
    readings: tuple[RegisterValue, ...]
    faults: tuple[Fault, ...]

    def value(self, name: str) -> int | None:
        return next((reading.value for reading in self.readings if reading.name == name), None)


@beartype
@dataclass(frozen=True, slots=True)
class MotorMetadata:
    motor_id: int
    identity: Identity | None
    proposed_role: str | None
    registers: tuple[RegisterValue, ...]
    faults: tuple[Fault, ...]
    skipped_registers: tuple[str, ...]

    def value(self, name: str) -> int | None:
        return RegisterBatch(self.registers, self.faults).value(name)


@beartype
@dataclass(frozen=True, slots=True)
class MotorTelemetry:
    motor_id: int
    torque_enabled: bool | None
    hardware_error: int | None
    position_counts: int | None
    velocity_raw: int | None
    pwm_raw: int | None
    load_raw: int | None
    voltage_raw: int | None
    temperature_c: int | None
    moving: bool | None
    moving_status: int | None
    tick_ms: int | None
    device_alert: bool
    faults: tuple[Fault, ...]

    @property
    def complete(self) -> bool:
        observed = (
            self.torque_enabled,
            self.hardware_error,
            self.position_counts,
            self.velocity_raw,
            self.pwm_raw,
            self.load_raw,
            self.voltage_raw,
            self.temperature_c,
            self.moving,
            self.moving_status,
            self.tick_ms,
        )
        return not self.faults and all(value is not None for value in observed)

    @property
    def voltage_v(self) -> float | None:
        return None if self.voltage_raw is None else self.voltage_raw / 10

    @property
    def velocity_rpm(self) -> float | None:
        return None if self.velocity_raw is None else self.velocity_raw * 0.229

    @property
    def estimated_load_percent(self) -> float | None:
        return None if self.load_raw is None else self.load_raw / 10


@beartype
@dataclass(frozen=True, slots=True)
class TelemetryFrame:
    sequence: int
    started_at: str
    finished_at: str
    monotonic_ns: int
    duration_ms: float
    requested_rate_hz: float
    deadline_missed: bool
    read_mode: ReadMode
    motors: tuple[MotorTelemetry, ...]


@beartype
@dataclass(frozen=True, slots=True)
class MetadataEvent:
    metadata: tuple[MotorMetadata, ...]
    config: ArmConfig
    observed_at: str
    kind: Literal["metadata"] = "metadata"
    schema_version: Literal[2] = 2


@beartype
@dataclass(frozen=True, slots=True)
class FrameEvent:
    frame: TelemetryFrame
    kind: Literal["frame"] = "frame"
    schema_version: Literal[2] = 2


@beartype
@dataclass(frozen=True, slots=True)
class StreamSummary:
    frames: int
    incomplete_frames: int
    deadline_misses: int
    elapsed_seconds: float
    achieved_rate_hz: float
    interrupted: bool
    port_closed: bool


@beartype
@dataclass(frozen=True, slots=True)
class EndEvent:
    summary: StreamSummary
    kind: Literal["end"] = "end"
    schema_version: Literal[2] = 2


@beartype
@dataclass(frozen=True, slots=True)
class Finding:
    motor_id: int | None
    level: Literal["info", "warning", "error"]
    code: str
    message: str


@beartype
@dataclass(frozen=True, slots=True)
class InspectionReport:
    metadata: MetadataEvent
    discovered: tuple[Identity, ...]
    frames: tuple[TelemetryFrame, ...]
    findings: tuple[Finding, ...]
    port_closed: bool
    schema_version: Literal[2] = 2
"""A narrow read interface and the official SDK adapter."""

from datetime import datetime
from typing import NamedTuple, Protocol, runtime_checkable

from dynamixel_sdk import COMM_RX_CORRUPT, COMM_SUCCESS, GroupSyncRead
from dynamixel_sdk.protocol2_packet_handler import Protocol2PacketHandler

from arm_observer.bus import ReadOnlyPort, read_registers
from arm_observer.models import (
    Fault,
    Identity,
    MotorTelemetry,
    ReadMode,
    RegisterBatch,
    RegisterValue,
)
from arm_observer.registers import BY_NAME, TELEMETRY, Register


def timestamp() -> str:
    return datetime.now().astimezone().isoformat(timespec="milliseconds")


@runtime_checkable
class Reader(Protocol):
    def identity(self, motor_id: int) -> Identity | None: ...
    def registers(self, motor_id: int, registers: tuple[Register, ...]) -> RegisterBatch: ...
    def telemetry(self, ids: tuple[int, ...], mode: ReadMode) -> tuple[MotorTelemetry, ...]: ...


class ReadReply(NamedTuple):
    data: tuple[int, ...]
    comm_result: int
    device_error: int


class Receipt(NamedTuple):
    motor_id: int
    reply: ReadReply


class Block(NamedTuple):
    address: int
    size: int
    registers: tuple[Register, ...]


BLOCKS = (
    Block(64, 7, (BY_NAME["torque_enable"], BY_NAME["hardware_error_status"])),
    Block(
        120,
        27,
        (
            BY_NAME["realtime_tick"],
            *(register for register in TELEMETRY if register.address >= 120),
        ),
    ),
)


class ReceiptPacket:
    """Retain per-device error bytes that GroupSyncRead otherwise discards."""

    def __init__(self, packet: Protocol2PacketHandler):
        self.packet = packet
        self.receipts: tuple[Receipt, ...] = ()

    def getProtocolVersion(self) -> float:
        return self.packet.getProtocolVersion()

    def syncReadTx(
        self, port: ReadOnlyPort, address: int, size: int, ids: list[int], count: int, fast: bool
    ) -> int:
        self.receipts = ()
        return self.packet.syncReadTx(port, address, size, ids, count, fast)

    def readRx(self, port: ReadOnlyPort, motor_id: int, size: int) -> ReadReply:
        data, result, error = self.packet.readRx(port, motor_id, size)
        if result == COMM_SUCCESS and len(data) != size:
            result = COMM_RX_CORRUPT
        reply = ReadReply(tuple(data), result, error)
        self.receipts += (Receipt(motor_id, reply),)
        return reply


class SyncGroup(NamedTuple):
    block: Block
    capture: ReceiptPacket
    group: GroupSyncRead


def decode_block(motor_id: int, block: Block, receipt: Receipt) -> RegisterBatch:
    reply = receipt.reply
    if reply.comm_result != COMM_SUCCESS or reply.device_error & 0x7F:
        fault = Fault(
            motor_id,
            "sync_read",
            reply.comm_result,
            reply.device_error,
            "Invalid per-device status; values unavailable",
        )
        return RegisterBatch((), (fault,))
    readings = []
    for register in block.registers:
        offset = register.address - block.address
        raw = int.from_bytes(bytes(reply.data[offset : offset + register.size]), "little")
        readings.append(
            RegisterValue(
                register.name,
                register.address,
                register.size,
                register.memory,
                raw,
                register.decode(raw),
                bool(reply.device_error & 0x80),
            )
        )
    return RegisterBatch(tuple(readings), ())


def optional_bool(value: int | None) -> bool | None:
    return None if value is None else bool(value)


def decode_telemetry(motor_id: int, batch: RegisterBatch) -> MotorTelemetry:
    return MotorTelemetry(
        motor_id,
        optional_bool(batch.value("torque_enable")),
        batch.value("hardware_error_status"),
        batch.value("present_position"),
        batch.value("present_velocity"),
        batch.value("present_pwm"),
        batch.value("present_load"),
        batch.value("present_input_voltage"),
        batch.value("present_temperature"),
        optional_bool(batch.value("moving")),
        batch.value("moving_status"),
        batch.value("realtime_tick"),
        any(reading.device_alert for reading in batch.readings),
        batch.faults,
    )


class SdkReader:
    def __init__(self, port: ReadOnlyPort, packet: Protocol2PacketHandler):
        self.port = port
        self.packet = packet
        self._ids: tuple[int, ...] = ()
        self._groups: tuple[SyncGroup, ...] = ()

    def identity(self, motor_id: int) -> Identity | None:
        model, result, error = self.packet.ping(self.port, motor_id)
        if result != COMM_SUCCESS or error & 0x7F:
            return None
        batch = RegisterBatch((), ())
        if model == 1060:
            batch = self.registers(motor_id, (BY_NAME["firmware_version"],))
        return Identity(
            motor_id, model, batch.value("firmware_version"), timestamp(), error, batch.faults
        )

    def registers(self, motor_id: int, registers: tuple[Register, ...]) -> RegisterBatch:
        return read_registers(self.port, self.packet, motor_id, registers)

    def _prepare_groups(self, ids: tuple[int, ...]) -> None:
        if ids == self._ids:
            return
        groups = []
        for block in BLOCKS:
            capture = ReceiptPacket(self.packet)
            group = GroupSyncRead(self.port, capture, block.address, block.size)
            for motor_id in ids:
                if not group.addParam(motor_id):
                    raise ValueError(f"Cannot add ID {motor_id} to SYNC_READ")
            groups.append(SyncGroup(block, capture, group))
        self._groups, self._ids = tuple(groups), ids

    def _sync_block(self, ids: tuple[int, ...], sync: SyncGroup) -> tuple[RegisterBatch, ...]:
        # txRxPacket can leave last_result=True after TX failure; reset before every cycle.
        sync.group.last_result = False
        sync.capture.receipts = ()
        result = sync.group.txRxPacket()
        if result != COMM_SUCCESS:
            return tuple(
                RegisterBatch(
                    (), (Fault(mid, "sync_read", result, 0, self.packet.getTxRxResult(result)),)
                )
                for mid in ids
            )
        batches = []
        for motor_id in ids:
            receipt = next(
                (item for item in sync.capture.receipts if item.motor_id == motor_id), None
            )
            if receipt is None:
                batches.append(
                    RegisterBatch(
                        (), (Fault(motor_id, "sync_read", -3001, 0, "No fresh response"),)
                    )
                )
            else:
                batches.append(decode_block(motor_id, sync.block, receipt))
        return tuple(batches)

    def telemetry(self, ids: tuple[int, ...], mode: ReadMode) -> tuple[MotorTelemetry, ...]:
        if not ids:
            return ()
        if mode == "unicast":
            return tuple(
                decode_telemetry(mid, self.registers(mid, (BY_NAME["realtime_tick"], *TELEMETRY)))
                for mid in ids
            )
        self._prepare_groups(ids)
        blocks = tuple(self._sync_block(ids, group) for group in self._groups)
        motors = []
        for index, motor_id in enumerate(ids):
            readings = tuple(reading for block in blocks for reading in block[index].readings)
            faults = tuple(fault for block in blocks for fault in block[index].faults)
            motors.append(decode_telemetry(motor_id, RegisterBatch(readings, faults)))
        return tuple(motors)

"""Acquisition services depend on Reader, not on Linux or the vendor SDK."""

import time
from collections.abc import Callable
from dataclasses import dataclass
from threading import Event as StopEvent

from beartype import beartype

from arm_observer.configuration import validate_polling
from arm_observer.models import (
    ArmConfig,
    Fault,
    FrameEvent,
    Identity,
    MetadataEvent,
    MotorMetadata,
    ReadMode,
    RegisterBatch,
    StreamSummary,
    TelemetryFrame,
)
from arm_observer.reader import Reader, decode_telemetry, timestamp
from arm_observer.registers import BY_NAME, REGISTERS

ESSENTIAL_METADATA = tuple(
    BY_NAME[name]
    for name in (
        "id",
        "baud_rate",
        "protocol_type",
        "operating_mode",
        "drive_mode",
        "homing_offset",
    )
)
Event = MetadataEvent | FrameEvent


@beartype
@dataclass(frozen=True, slots=True)
class PollOptions:
    rate_hz: float = 20.0
    duration_seconds: float = 10.0
    frame_limit: int = 0
    metadata_every_seconds: float = 30.0
    read_mode: ReadMode = "sync"

    def __post_init__(self) -> None:
        validate_polling(self.rate_hz, self.duration_seconds, self.frame_limit)
        validate_polling(1.0, self.metadata_every_seconds, 0)


@beartype
def read_metadata(reader: Reader, config: ArmConfig, full: bool = False) -> MetadataEvent:
    motors = tuple(
        read_motor_metadata(reader, config, mid, full) for mid in config.bus.expected_ids
    )
    return MetadataEvent(motors, config, timestamp())


def read_motor_metadata(
    reader: Reader, config: ArmConfig, motor_id: int, full: bool
) -> MotorMetadata:
    identity = reader.identity(motor_id)
    role = config.role(motor_id)
    if identity is None:
        fault = Fault(motor_id, "identity", -3001, 0, "No PING response")
        return MotorMetadata(motor_id, None, role, (), (fault,), ())
    if identity.model_number != 1060:
        fault = Fault(motor_id, "model", -9000, 0, "Unsupported model; identity only")
        return MotorMetadata(motor_id, identity, role, (), (fault,), ())
    firmware = identity.firmware_version or 0
    candidates = REGISTERS if full else ESSENTIAL_METADATA
    supported = tuple(register for register in candidates if register.minimum_firmware <= firmware)
    skipped = tuple(
        register.name for register in candidates if register.minimum_firmware > firmware
    )
    batch = reader.registers(motor_id, supported)
    return MotorMetadata(
        motor_id, identity, role, batch.readings, identity.faults + batch.faults, skipped
    )


def discover(reader: Reader, ids: tuple[int, ...]) -> tuple[Identity, ...]:
    return tuple(identity for mid in ids if (identity := reader.identity(mid)) is not None)


def read_frame(
    reader: Reader, metadata: MetadataEvent, sequence: int, options: PollOptions, deadline_ns: int
) -> TelemetryFrame:
    started_at, started_ns = timestamp(), time.monotonic_ns()
    supported = tuple(
        motor.motor_id
        for motor in metadata.metadata
        if motor.identity is not None and motor.identity.model_number == 1060
    )
    readings = reader.telemetry(supported, options.read_mode)
    motors = []
    for motor in metadata.metadata:
        reading = next((item for item in readings if item.motor_id == motor.motor_id), None)
        if reading is None:
            fault = Fault(
                motor.motor_id, "telemetry", -9000, 0, "No eligible model or no fresh telemetry"
            )
            reading = decode_telemetry(motor.motor_id, RegisterBatch((), (fault,)))
        motors.append(reading)
    finished_ns = time.monotonic_ns()
    return TelemetryFrame(
        sequence,
        started_at,
        timestamp(),
        started_ns,
        (finished_ns - started_ns) / 1e6,
        options.rate_hz,
        finished_ns > deadline_ns,
        options.read_mode,
        tuple(motors),
    )


@dataclass(slots=True)
class Cadence:
    period_ns: int
    next_ns: int
    end_ns: int | None

    def wait(self, stop_event: StopEvent | None = None) -> bool:
        now = time.monotonic_ns()
        while now < self.next_ns:
            if stopped(stop_event):
                return False
            if self.end_ns is not None and now >= self.end_ns:
                return False
            time.sleep(min((self.next_ns - now) / 1e9, 0.1))
            now = time.monotonic_ns()
        return not stopped(stop_event) and (
            self.end_ns is None or now < self.end_ns
        )

    def advance(self) -> None:
        now = time.monotonic_ns()
        periods = max(1, (now - self.next_ns) // self.period_ns + 1)
        self.next_ns += periods * self.period_ns


@dataclass(slots=True)
class Counters:
    frames: int = 0
    incomplete: int = 0
    misses: int = 0
    first_frame_ns: int | None = None
    last_frame_ns: int | None = None

    def add(self, frame: TelemetryFrame) -> None:
        self.frames += 1
        self.incomplete += int(not all(motor.complete for motor in frame.motors))
        self.misses += int(frame.deadline_missed)
        if self.first_frame_ns is None:
            self.first_frame_ns = frame.monotonic_ns
        self.last_frame_ns = frame.monotonic_ns

    def summary(self, elapsed: float, interrupted: bool) -> StreamSummary:
        span = (self.last_frame_ns or 0) - (self.first_frame_ns or 0)
        rate = (self.frames - 1) * 1e9 / span if span > 0 else 0.0
        return StreamSummary(
            self.frames, self.incomplete, self.misses, elapsed, rate, interrupted, False
        )


@beartype
def observe(
    reader: Reader,
    config: ArmConfig,
    options: PollOptions,
    emit: Callable[[Event], None],
    full_metadata: bool = False,
    stop_event: StopEvent | None = None,
) -> StreamSummary:
    metadata = read_metadata(reader, config, full_metadata)
    emit(metadata)
    start = time.monotonic_ns()
    end = start + int(options.duration_seconds * 1e9) if options.duration_seconds else None
    cadence = Cadence(max(1, int(1e9 / options.rate_hz)), start, end)
    counters = Counters()
    refresh_ns = int(options.metadata_every_seconds * 1e9)
    next_refresh = start + refresh_ns
    interrupted = False
    try:
        while within_limit(counters.frames, options.frame_limit) and cadence.wait(stop_event):
            if refresh_ns and time.monotonic_ns() >= next_refresh:
                metadata = read_metadata(reader, config, full_metadata)
                emit(metadata)
                next_refresh = time.monotonic_ns() + refresh_ns
            if stopped(stop_event):
                break
            frame = read_frame(
                reader, metadata, counters.frames, options, cadence.next_ns + cadence.period_ns
            )
            counters.add(frame)
            emit(FrameEvent(frame))
            cadence.advance()
    except KeyboardInterrupt:
        interrupted = True
    return counters.summary(
        (time.monotonic_ns() - start) / 1e9,
        interrupted or stopped(stop_event),
    )


def within_limit(count: int, limit: int) -> bool:
    return limit == 0 or count < limit


def stopped(stop_event: StopEvent | None) -> bool:
    return stop_event is not None and stop_event.is_set()
"""Read-only live acquisition. No port is opened by construction or status queries."""
from collections.abc import Callable
from dataclasses import dataclass, replace
from pathlib import Path
from threading import Event, Lock, Thread
from uuid import uuid4

from arm_observer.bus import open_bus
from arm_observer.models import ArmConfig, EndEvent, FrameEvent, MetadataEvent, StreamSummary
from arm_observer.observer import PollOptions, observe
from arm_observer.output import JsonlSink, report_stem
from arm_observer.reader import SdkReader

StreamEvent = MetadataEvent | FrameEvent
Acquire = Callable[[ArmConfig, PollOptions, Callable[[StreamEvent], None], Event], StreamSummary]


def empty_summary(port_closed: bool = False) -> StreamSummary:
    return StreamSummary(0, 0, 0, 0.0, 0.0, False, port_closed)


def run_acquisition(
    config: ArmConfig, options: PollOptions, emit: Callable[[StreamEvent], None], stop: Event
) -> StreamSummary:
    with open_bus(config.bus.device, config.bus.baudrate) as (port, packet):
        summary = observe(SdkReader(port, packet), config, options, emit, stop_event=stop)
    return replace(summary, port_closed=True)


@dataclass(frozen=True, slots=True)
class LiveSnapshot:
    state: str = "idle"
    session_id: str | None = None
    port_closed: bool | None = True
    metadata: MetadataEvent | None = None
    frame: FrameEvent | None = None
    summary: StreamSummary | None = None
    log_path: Path | None = None
    error: str | None = None


class LiveMonitor:
    def __init__(self, config: ArmConfig, reports: Path, acquire: Acquire = run_acquisition):
        self.config, self.reports, self.acquire = config, reports, acquire
        self._lock = Lock()
        self._stop = Event()
        self._thread: Thread | None = None
        self._snapshot = LiveSnapshot()

    def snapshot(self) -> LiveSnapshot:
        with self._lock:
            return self._snapshot

    def start(self, duration_seconds: float = 10.0) -> LiveSnapshot:
        if type(duration_seconds) not in (int, float):
            raise ValueError("Duration must be numeric")
        options = PollOptions(duration_seconds=float(duration_seconds))
        with self._lock:
            if self._thread is not None and self._thread.is_alive():
                raise ValueError("Already running; wait for port closure")
            self.reports.mkdir(parents=True, exist_ok=True)
            self._snapshot = LiveSnapshot(
                state="starting", session_id=str(uuid4()), port_closed=False,
                log_path=self.reports / (report_stem("live") + ".jsonl"),
            )
            self._stop = Event()
            self._thread = Thread(target=self._run, args=(options,), daemon=True)
            self._thread.start()
            return self._snapshot

    def stop(self) -> LiveSnapshot:
        with self._lock:
            if self._thread is not None and self._thread.is_alive():
                self._stop.set()
                self._snapshot = replace(self._snapshot, state="stopping")
            return self._snapshot

    def join(self, timeout: float = 10.0) -> bool:
        thread = self._thread
        if thread is not None:
            thread.join(timeout)
        return thread is None or not thread.is_alive()

    def _receive(self, event: StreamEvent) -> None:
        with self._lock:
            fields = {"metadata": event} if isinstance(event, MetadataEvent) else {"frame": event}
            # A stop requested during a read stays visible until the finally block completes.
            state = "stopping" if self._stop.is_set() else "running"
            self._snapshot = replace(self._snapshot, state=state, **fields)

    def _record(self, options: PollOptions, sink: JsonlSink) -> StreamSummary:
        def emit(event: StreamEvent) -> None:
            sink.emit(event)
            self._receive(event)
        return self.acquire(self.config, options, emit, self._stop)

    def _run(self, options: PollOptions) -> None:
        path = self.snapshot().log_path
        summary, error = empty_summary(), None
        try:
            assert path is not None
            with path.open("x", encoding="utf-8") as file:
                sink = JsonlSink(file)
                try:
                    summary = self._record(options, sink)
                except Exception as exc:
                    # No stale success or guessed closure after an exceptional SDK/close failure.
                    error = f"{type(exc).__name__}: {exc}"
                sink.emit(EndEvent(summary))
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"
        with self._lock:
            self._snapshot = replace(
                self._snapshot, state="error" if error else "stopped",
                summary=summary, port_closed=None if error else summary.port_closed, error=error,
            )

"""Local bridge: status is passive; only explicit start acquires the read-only bus."""
import argparse
import json
from dataclasses import asdict
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from arm_observer.configuration import load_config
from arm_observer.live import LiveMonitor


def origin_allowed(origin: str | None, port: int) -> bool:
    return origin is None or origin in {f"http://127.0.0.1:{port}", f"http://localhost:{port}"}


def status_bytes(monitor: LiveMonitor) -> bytes:
    return json.dumps(asdict(monitor.snapshot()), default=str, allow_nan=False).encode()


def handler_for(monitor: LiveMonitor, port: int) -> type[BaseHTTPRequestHandler]:
    class Handler(BaseHTTPRequestHandler):
        def respond(self, code: int, content: bytes) -> None:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(content)))
            self.end_headers()
            try:
                self.wfile.write(content)
            except (BrokenPipeError, ConnectionResetError):
                pass

        def do_GET(self) -> None:
            if self.path == "/api/status":
                self.respond(200, status_bytes(monitor))
            else:
                self.respond(404, b'{"error":"Not found"}')

        def do_POST(self) -> None:
            if not origin_allowed(self.headers.get("Origin"), port):
                self.respond(403, b'{"error":"Invalid origin"}')
                return
            try:
                size = int(self.headers.get("Content-Length", 0))
                if not 0 < size <= 1024:
                    raise ValueError("Invalid payload size")
                payload = json.loads(self.rfile.read(size))
                self.apply_request(payload)
                self.respond(200, status_bytes(monitor))
            except (ValueError, TypeError) as exc:
                self.respond(400, json.dumps({"error": str(exc)}).encode())

        def apply_request(self, payload: object) -> None:
            if not isinstance(payload, dict):
                raise ValueError("Object required")
            if self.path == "/api/start" and set(payload) == {"duration_seconds"}:
                monitor.start(payload["duration_seconds"])
            elif self.path == "/api/stop" and not payload:
                monitor.stop()
            else:
                raise ValueError("Unknown action or field; bridge has no write API")

        def log_message(self, format: str, *args: object) -> None:
            pass
    return Handler


def main() -> None:
    root = Path(__file__).resolve().parents[2]
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--port", type=int, default=8085)
    parser.add_argument("--config", type=Path, default=root / "config/arm.toml")
    parser.add_argument("--reports", type=Path, default=root / "reports")
    args = parser.parse_args()
    monitor = LiveMonitor(load_config(args.config), args.reports)
    server = ThreadingHTTPServer(("127.0.0.1", args.port), handler_for(monitor, args.port))
    print(f"READ bridge http://127.0.0.1:{args.port} (idle; no serial connection)", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        monitor.stop()
        closed = monitor.join()
        server.server_close()
        if not closed:
            print("Acquisition still closing; closure has not been confirmed", flush=True)


if __name__ == "__main__":
    main()

