export const meta = {
  name: 'rereview-id3-motion',
  description: 'Second adversarial review of the fixed ID3 motion command (release guarantee, evidence checks, pacing, signals) using the serial emulator',
  phases: [{ title: 'Refute' }, { title: 'Judge' }],
}
const COMMON = `READ-ONLY review. Do NOT modify project files. Do NOT open any real serial port or /dev/tty*, and do NOT run arm-status/arm-live/arm-id3-open against hardware. Do NOT touch servers on ports 8081-8087. Scratch only under /tmp/claude-1000/. A serial-level 5x XL430 emulator from a previous review exists at /tmp/claude-1000/-home-inaho-omen-Project-my-dynamixel-arm-sandbox/c1ea256b-b2b7-479c-b8cb-27a6804a8c28/scratchpad/lensA (emu.py, common.py, p0_baseline.py, p2_interrupt_busy.py, p3_alert_and_ioerror.py); copy it into your own scratch folder before extending it. Run with: rtk proxy uv run --project /home/inaho-omen/Project/my_dynamixel_arm_sandbox --locked --no-sync python <script>. Prefix shell commands with rtk proxy.
Code: /home/inaho-omen/Project/my_dynamixel_arm_sandbox/src/arm_observer/id3_motion.py and motion_guard.py; tests/test_id3_motion.py; spec temp/id3_motion_spec.md (revised 23:17).
The previous review found and the author fixed: SDK busy flag after interrupts (now Actuator.recover before every release attempt), log-before-send, unreported torque-off failure (now torque_off_confirmed + exit code 3), restores after failed torque-off (now skipped), SIGTERM/SIGHUP (now mapped to KeyboardInterrupt in execute), evidence consistency checks, window margin 15, status_return_level precondition, final torque read, summary JSON, deadline pacing.
Try to REFUTE: "after the first write, every exit path attempts torque OFF, reports truthfully whether it was confirmed, writes nothing else if it was not, never writes outside the ID3 envelope, and the evidence parser cannot yield a sign that drives ID3 further into the fold". refuted=true only with a reproduced failing probe.`
const VERDICT = { type: 'object', properties: { lens: { type: 'string' }, refuted: { type: 'boolean' }, probes: { type: 'array', items: { type: 'object', properties: { what: { type: 'string' }, outcome: { type: 'string' } }, required: ['what', 'outcome'] } }, blocking: { type: 'array', items: { type: 'string' } }, non_blocking: { type: 'array', items: { type: 'string' } } }, required: ['lens', 'refuted', 'probes', 'blocking', 'non_blocking'] }
const LENSES = [
  'Lens E: release and reporting under faults, via the emulator and the real SDK: Ctrl-C or SIGTERM at many points (each sample, each write, during release, a second Ctrl-C inside release), serial exceptions, status timeouts, lost Torque=0 packets, torque_enable read-back lying (stays 1), emit/log failures at every point, KeyboardInterrupt during prepare and dry run. Check exit codes, stdout/stderr text, JSONL and summary contents.',
  'Lens F: evidence parser and motion direction. Fuzz load_evidence with crafted JSON (types, wrap cases, mismatched delta/sign/counts, duplicate keys, huge numbers, NaN, nested types, missing keys) and confirm any accepted evidence yields a sign equal to the wrap-aware sign of after-before and that the target computed by run_motion always moves away from the folded count in that direction. Also check pacing logic (pace) cannot spin or burst and that timeouts still trigger with slow transactions.',
]
phase('Refute')
const vs = (await parallel(LENSES.map((l, i) => () => agent(`${COMMON}\n\n${l}`, { label: `refute-${'EF'[i]}`, phase: 'Refute', schema: VERDICT })))).filter(Boolean)
phase('Judge')
const judge = await agent(`Judge (Japanese): is the fixed ID3 command safe to run once on hardware given the user keeps a hand on the supply OUTPUT OFF? 判定, blocking(再現根拠), 実行前必須事項, non-blocking. Verdicts: ${JSON.stringify(vs)}`, { label: 'judge', phase: 'Judge' })
return { vs, judge }

