from pathlib import Path
p=Path('scripts/derive_id3_direction.py'); s=p.read_text()
old='''    if any(type(c) is not int for c in counts) or any(m["torque_enabled"] is not False for m in motors):'''
new='''    unknown = any(type(c) is not int for c in counts)
    if unknown or any(m["torque_enabled"] is not False for m in motors):'''
assert s.count(old)==1; p.write_text(s.replace(old,new))
p=Path('src/arm_observer/id3_motion.py'); s=p.read_text()
old='''def cad_problem(record: dict) -> str | None:
    sign, folded = record.get("opening_count_sign"), record.get("folded_count")
    read = record.get("folded_read") or {}
    if record.get("motor_id") != MOTOR_ID or type(sign) is not int or sign not in (1, -1):
        return "CAD direction evidence must give an integer +-1 sign for ID3"
    if (record.get("derivation") or {}).get("opening_count_sign") != sign:
        return "CAD direction evidence sign differs from its derivation"
    if type(folded) is not int or read.get("folded_count") != folded or not read.get("frames"):
        return "CAD direction evidence needs the folded count from a completed READ"
    if not record.get("sources"):
        return "CAD direction evidence must list its hashed CAD sources"
    return None
'''
new='''def cad_sign_problem(record: dict) -> str | None:
    sign = record.get("opening_count_sign")
    if record.get("motor_id") != MOTOR_ID or type(sign) is not int or sign not in (1, -1):
        return "CAD direction evidence must give an integer +-1 sign for ID3"
    if (record.get("derivation") or {}).get("opening_count_sign") != sign:
        return "CAD direction evidence sign differs from its derivation"
    return None


def cad_problem(record: dict) -> str | None:
    folded, read = record.get("folded_count"), record.get("folded_read") or {}
    if type(folded) is not int or read.get("folded_count") != folded or not read.get("frames"):
        return "CAD direction evidence needs the folded count from a completed READ"
    if not record.get("sources"):
        return "CAD direction evidence must list its hashed CAD sources"
    return cad_sign_problem(record)
'''
assert s.count(old)==1; p.write_text(s.replace(old,new)); print('ok')
EOF
